import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";
import { formatDate, formatMoney, fromCents, monthStartTimestamp, priorityLabel, scopeLabel, toCents } from "@/lib/finance";
import { trpc } from "@/lib/trpc";
import { emptyWorkspaceFilters, filterWorkspaceSnapshot, WorkspaceFilterBar } from "@/components/WorkspaceFilterBar";
import { AlertTriangle, CalendarCheck2, Check, ChevronRight, CircleDollarSign, ClipboardCheck, FileClock, Goal, ListTodo, Pencil, Plus, Scale, Target, Trash2, WalletCards } from "lucide-react";
import { FormEvent, useMemo, useState } from "react";
import { toast } from "sonner";

type PlanningView = "budget" | "goals" | "debts" | "receivables" | "payables" | "recurring" | "tasks" | "reviews" | "decisions";

const planningTabs: { value: PlanningView; label: string }[] = [
  { value: "budget", label: "Presupuesto" },
  { value: "goals", label: "Objetivos" },
  { value: "debts", label: "Deudas" },
  { value: "receivables", label: "Por cobrar" },
  { value: "payables", label: "Por pagar" },
  { value: "recurring", label: "Recurrentes" },
  { value: "tasks", label: "Tareas" },
  { value: "reviews", label: "Revisiones" },
  { value: "decisions", label: "Decisiones" },
];

function PlanningEmpty({ icon: Icon, title, text, actionLabel, onAction }: { icon: typeof Target; title: string; text: string; actionLabel: string; onAction: () => void }) {
  return <div className="planning-empty"><div className="empty-icon"><Icon className="size-5" /></div><h3>{title}</h3><p>{text}</p><Button variant="outline" onClick={onAction}>{actionLabel}</Button></div>;
}

export default function Planning() {
  const { data, isLoading } = trpc.finance.dashboard.useQuery();
  const utils = trpc.useUtils();
  const [view, setView] = useState<PlanningView>("budget");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [workspaceFilters, setWorkspaceFilters] = useState(emptyWorkspaceFilters);
  const refresh = async () => { await utils.finance.dashboard.invalidate(); setDialogOpen(false); };
  const scopedData = useMemo(() => data ? filterWorkspaceSnapshot(data, workspaceFilters) : undefined, [data, workspaceFilters]);
  const currency = data?.profile?.currency ?? "MXN";

  if (isLoading || !data) return <div className="page-loading">Preparando tus planes financieros…</div>;

  const title = {
    budget: ["Presupuesto mensual", "Planifica importes y contrasta el presupuesto con tus movimientos manuales."],
    goals: ["Objetivos financieros", "Convierte prioridades en aportaciones, plazos y escenarios comprensibles."],
    debts: ["Deudas y obligaciones", "Mantén saldo, interés, vencimiento y prioridad en una sola vista."],
    receivables: ["Cuentas por cobrar", "Registra cobros esperados de clientes o personas sin confundirlos con ingresos recibidos."],
    payables: ["Cuentas por pagar", "Registra obligaciones con proveedores, contador, socios, amistades u otros acreedores."],
    recurring: ["Plantillas recurrentes", "Crea y aplica manualmente plantillas para cualquier gasto o ingreso repetitivo."],
    tasks: ["Próximas acciones", "Gestiona tareas que llevan tus decisiones a la práctica, sin ejecutar operaciones."],
    reviews: ["Revisiones mensuales", "Cierra cada periodo con resultados, observaciones y acciones prioritarias."],
    decisions: ["Decisiones explicables", "Registra el contexto, supuestos, riesgos y alternativas de cada decisión relevante."],
  }[view];

  return <div className="space-y-7">
    <header className="page-heading"><div><p className="eyebrow">Planificación y seguimiento</p><h1>{title[0]}</h1><p>{title[1]}</p></div><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button className="btn-primary" onClick={() => setDialogOpen(true)}><Plus className="size-4" /> {view === "budget" ? "Añadir partida" : view === "goals" ? "Crear objetivo" : view === "debts" ? "Añadir deuda" : view === "receivables" ? "Registrar CxC" : view === "payables" ? "Registrar CxP" : view === "recurring" ? "Crear plantilla" : view === "tasks" ? "Crear tarea" : view === "reviews" ? "Crear revisión" : "Registrar decisión"}</Button></DialogTrigger><DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{view === "budget" ? "Nueva partida presupuestaria" : view === "goals" ? "Nuevo objetivo" : view === "debts" ? "Nueva deuda" : view === "receivables" ? "Nueva cuenta por cobrar" : view === "payables" ? "Nueva cuenta por pagar" : view === "recurring" ? "Nueva plantilla recurrente" : view === "tasks" ? "Nueva tarea" : view === "reviews" ? "Nueva revisión mensual" : "Nueva decisión"}</DialogTitle><DialogDescription>Se guardará únicamente en tu espacio privado de Meximoney.</DialogDescription></DialogHeader>{view === "budget" && <BudgetForm categories={data.categories} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "goals" && <GoalForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "debts" && <DebtForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "receivables" && <ReceivableForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "payables" && <PayableForm currency={currency} entities={data.entities} projects={data.projects} onDone={refresh} />}{view === "recurring" && <RecurringTemplateForm snapshot={data} onDone={refresh} />}{view === "tasks" && <TaskForm goals={data.goals} debts={data.debts} onDone={refresh} />}{view === "reviews" && <ReviewForm snapshot={data} onDone={refresh} />}{view === "decisions" && <DecisionForm onDone={refresh} />}</DialogContent></Dialog></header>
    <Tabs className="w-full min-w-0" value={view} onValueChange={value => setView(value as PlanningView)}><TabsList className="planning-tabs">{planningTabs.map(tab => <TabsTrigger key={tab.value} value={tab.value}>{tab.label}</TabsTrigger>)}</TabsList></Tabs>
    <WorkspaceFilterBar snapshot={data} filters={workspaceFilters} onChange={setWorkspaceFilters} />
    {view === "budget" && <BudgetPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "goals" && <GoalsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "debts" && <DebtsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "receivables" && <ReceivablesPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} refresh={refresh} />}
    {view === "payables" && <PayablesPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} refresh={refresh} />}
    {view === "recurring" && <RecurringTemplatesPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} refresh={refresh} />}
    {view === "tasks" && <TasksPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} refresh={refresh} />}
    {view === "reviews" && <ReviewsPanel snapshot={scopedData} currency={currency} onCreate={() => setDialogOpen(true)} />}
    {view === "decisions" && <DecisionsPanel snapshot={scopedData} onCreate={() => setDialogOpen(true)} />}
  </div>;
}

function BudgetPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const remove = trpc.finance.budgets.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  const budgets = snapshot.budgets.slice().sort((a: any, b: any) => new Date(b.periodStart).getTime() - new Date(a.periodStart).getTime());
  const actualFor = (budget: any) => snapshot.transactions.filter((transaction: any) => transaction.categoryId === budget.categoryId && transaction.type === budget.type && new Date(transaction.occurredAt).getFullYear() === new Date(budget.periodStart).getFullYear() && new Date(transaction.occurredAt).getMonth() === new Date(budget.periodStart).getMonth()).reduce((sum: number, transaction: any) => sum + transaction.amountCents, 0);
  return <section className="content-card">{budgets.length === 0 ? <PlanningEmpty icon={CircleDollarSign} title="No hay partidas presupuestarias" text="Crea una partida por categoría y periodo para comparar tu previsión con los movimientos que registres." actionLabel="Crear primera partida" onAction={onCreate} /> : <div className="budget-board">{budgets.map((budget: any) => { const actual = actualFor(budget); const difference = actual - budget.plannedCents; const category = snapshot.categories.find((item: any) => item.id === budget.categoryId); return <article key={budget.id} className="budget-card"><div className="card-title-row"><div><span className={`scope-pill scope-${budget.scope}`}>{scopeLabel[budget.scope]}</span><h2 className="mt-3">{category?.name ?? "Sin categoría"}</h2><p className="capitalize">{formatDate(budget.periodStart, { month: "long", year: "numeric" })} · {budget.type === "income" ? "Ingreso" : "Gasto"}</p></div><button className="row-action-danger" aria-label="Eliminar partida" onClick={() => { if (confirm("¿Eliminar esta partida presupuestaria?") ) remove.mutate({ id: budget.id }); }}><Trash2 className="size-4" /></button></div><div className="budget-figures"><div><span>Previsto</span><strong>{formatMoney(budget.plannedCents, currency)}</strong></div><div><span>Real</span><strong>{formatMoney(actual, currency)}</strong></div></div><div className="budget-progress"><span style={{ width: `${budget.plannedCents ? Math.min(100, (actual / budget.plannedCents) * 100) : 0}%` }} /></div><div className="budget-footer"><span>Variación</span><b className={difference > 0 && budget.type === "expense" ? "amount-negative" : "amount-positive"}>{difference >= 0 ? "+" : "−"}{formatMoney(Math.abs(difference), currency)}</b></div></article>; })}</div>}</section>;
}

function GoalsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const remove = trpc.finance.goals.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  const goals = snapshot.goals.filter((goal: any) => goal.status !== "cancelled");
  return <section className="goals-layout">{goals.length === 0 ? <section className="content-card"><PlanningEmpty icon={Goal} title="Sin objetivos financieros" text="Define una meta de emergencia, patrimonio, vivienda, negocio o jubilación y calcula una aportación sostenible." actionLabel="Crear objetivo" onAction={onCreate} /></section> : goals.map((goal: any) => { const remaining = Math.max(0, goal.targetCents - goal.currentCents); const percent = goal.targetCents ? Math.min(100, (goal.currentCents / goal.targetCents) * 100) : 0; const months = goal.monthlyContributionCents > 0 ? Math.ceil(remaining / goal.monthlyContributionCents) : null; return <article className="content-card goal-detail-card" key={goal.id}><div className="goal-detail-top"><div><span className={`scope-pill scope-${goal.scope}`}>{scopeLabel[goal.scope]}</span><h2>{goal.name}</h2><p>{priorityLabel[goal.priority]} prioridad · {goal.targetDate ? `Meta: ${formatDate(goal.targetDate)}` : "Fecha objetivo pendiente"}</p></div><button className="row-action-danger" aria-label="Eliminar objetivo" onClick={() => { if (confirm("¿Eliminar este objetivo?") ) remove.mutate({ id: goal.id }); }}><Trash2 className="size-4" /></button></div><div className="goal-number"><strong>{percent.toFixed(0)}%</strong><span>{formatMoney(goal.currentCents, goal.currency)} de {formatMoney(goal.targetCents, goal.currency)}</span></div><div className="progress-track progress-large"><span style={{ width: `${percent}%` }} /></div><div className="scenario-grid"><div><small>Falta por cubrir</small><strong>{formatMoney(remaining, goal.currency)}</strong></div><div><small>Aportación mensual</small><strong>{formatMoney(goal.monthlyContributionCents, goal.currency)}</strong></div><div><small>Escenario base</small><strong>{months === null ? "Define aportación" : `${months} meses`}</strong></div></div>{goal.notes ? <p className="goal-notes"><strong>Supuesto:</strong> {goal.notes}</p> : null}</article>; })}</section>;
}

function DebtsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const remove = trpc.finance.debts.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  const debts = snapshot.debts.filter((debt: any) => debt.status !== "paid");
  return <section className="content-card">{debts.length === 0 ? <PlanningEmpty icon={WalletCards} title="Sin deudas activas" text="Registra cualquier obligación relevante para incorporar sus vencimientos y coste estimado a tus revisiones." actionLabel="Añadir deuda" onAction={onCreate} /> : <div className="debt-list">{debts.map((debt: any) => { const monthlyInterest = debt.interestRateBps ? (debt.balanceCents * debt.interestRateBps) / 120000 : null; return <article key={debt.id} className="debt-row"><div className={`debt-priority priority-${debt.priority}`} /><div className="debt-main"><div><span className={`scope-pill scope-${debt.scope}`}>{scopeLabel[debt.scope]}</span><h2>{debt.name}</h2><p>{debt.creditor || "Acreedor pendiente"} · {debt.type.replace("_", " ")}</p></div><div className="debt-amount"><strong>{formatMoney(debt.balanceCents, debt.currency)}</strong><small>Saldo actual</small></div></div><div className="debt-meta"><span><small>Tasa anual</small><strong>{debt.interestRateBps === null ? "Sin confirmar" : `${(debt.interestRateBps / 100).toFixed(2)}%`}</strong></span><span><small>Cuota mínima</small><strong>{formatMoney(debt.minimumPaymentCents, debt.currency)}</strong></span><span><small>Interés mensual estimado</small><strong>{monthlyInterest === null ? "—" : formatMoney(Math.round(monthlyInterest), debt.currency)}</strong></span><span><small>Próximo vencimiento</small><strong>{debt.nextDueAt ? formatDate(debt.nextDueAt) : "Pendiente"}</strong></span></div><div className="debt-foot"><p>{debt.notes || "Completa condiciones y documentos para analizar alternativas de forma trazable."}</p><button className="row-action-danger" aria-label="Eliminar deuda" onClick={() => { if (confirm("¿Eliminar esta deuda?") ) remove.mutate({ id: debt.id }); }}><Trash2 className="size-4" /></button></div></article>; })}</div>}</section>;
}

function ReceivablesPanel({ snapshot, onCreate, refresh }: { snapshot: any; onCreate: () => void; refresh: () => void }) {
  const remove = trpc.finance.workspace.receivables.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removePayment = trpc.finance.workspace.receivables.paymentRemove.useMutation({ onSuccess: () => { toast.success("Abono eliminado y saldo recalculado"); refresh(); }, onError: error => toast.error(error.message) });
  const items = snapshot.receivables.slice().sort((a: any, b: any) => (a.dueAt ? new Date(a.dueAt).getTime() : Infinity) - (b.dueAt ? new Date(b.dueAt).getTime() : Infinity));
  const statusLabel: Record<string, string> = { pending: "Pendiente", overdue: "Vencida", paid: "Pagada", reconciled: "Conciliada" };
  return <section className="content-card">{items.length === 0 ? <PlanningEmpty icon={CircleDollarSign} title="Sin cuentas por cobrar" text="Registra un cobro esperado de YMC, ELM o Personal. No contará como ingreso hasta que registres manualmente el dinero recibido." actionLabel="Registrar primera CxC" onAction={onCreate} /> : <div className="debt-list">{items.map((item: any) => { const entity = snapshot.entities.find((row: any) => row.id === item.entityId); const payments = snapshot.receivablePayments.filter((payment: any) => payment.receivableId === item.id); const paidCents = payments.reduce((sum: number, payment: any) => sum + payment.amountCents, 0); const remainingCents = Math.max(0, item.amountCents - paidCents); const unlinkedPayment = payments.find((payment: any) => !payment.linkedTransactionId); const incomeCandidates = snapshot.transactions.filter((transaction: any) => transaction.type === "income" && transaction.currency === item.currency && transaction.reviewStatus === "approved"); const canOpenPayment = remainingCents > 0 || Boolean(unlinkedPayment); return <article key={item.id} className="debt-row"><div className={`debt-priority priority-${item.status === "overdue" ? "critical" : item.status === "pending" ? "medium" : "low"}`} /><div className="debt-main"><div><span className={`scope-pill scope-${item.scope}`}>{scopeLabel[item.scope]}</span><h2>{item.counterparty}</h2><p>{item.origin}{entity ? ` · ${entity.shortCode || entity.name}` : " · Personal"}</p></div><div className="debt-amount"><strong>{formatMoney(item.amountCents, item.currency)}</strong><small>{statusLabel[item.status]}</small></div></div><div className="debt-meta"><span><small>Abonado</small><strong>{formatMoney(paidCents, item.currency)}</strong></span><span><small>Saldo pendiente</small><strong>{formatMoney(remainingCents, item.currency)}</strong></span><span><small>Vence</small><strong>{item.dueAt ? formatDate(item.dueAt) : "Sin fecha"}</strong></span><span><small>Conciliación</small><strong>{item.status === "reconciled" ? "Ingreso vinculado" : item.status === "paid" ? "Falta vincular ingreso" : "Pendiente"}</strong></span></div><div className="debt-foot"><p>{item.notes || "Cada abono puede vincularse al ingreso real registrado, sin crear movimientos nuevos."}</p><div className="flex flex-wrap gap-2">{canOpenPayment ? <Dialog><DialogTrigger asChild><Button size="sm" variant="outline">{unlinkedPayment ? "Vincular ingreso" : "Registrar abono"}</Button></DialogTrigger><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>{unlinkedPayment ? "Conciliar abono con ingreso real" : "Registrar abono parcial"}</DialogTitle><DialogDescription>El abono no crea un ingreso. Selecciona, si existe, el movimiento de ingreso que ya registraste manualmente.</DialogDescription></DialogHeader><ReceivablePaymentForm receivable={item} payment={unlinkedPayment} remainingCents={remainingCents} incomeCandidates={incomeCandidates} onDone={refresh} /></DialogContent></Dialog> : <Button size="sm" variant="outline" disabled>Conciliada</Button>}<button className="row-action-danger" aria-label="Eliminar cuenta por cobrar" onClick={() => { if (confirm("¿Eliminar esta cuenta por cobrar manual?") ) remove.mutate({ id: item.id }); }}><Trash2 className="size-4" /></button></div></div>{payments.length ? <div className="mt-3 space-y-2 border-t pt-3">{payments.map((payment: any) => { const income = snapshot.transactions.find((transaction: any) => transaction.id === payment.linkedTransactionId); return <div key={payment.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-muted/45 px-3 py-2 text-sm"><span><strong>{formatMoney(payment.amountCents, payment.currency)}</strong> · {formatDate(payment.paidAt)} · {income ? `Ingreso vinculado: ${income.notes || `#${income.id}`}` : "Sin ingreso vinculado"}</span><button className="row-action-danger" aria-label="Eliminar abono" onClick={() => { if (confirm("¿Eliminar este abono y recalcular el saldo?") ) removePayment.mutate({ id: payment.id }); }}><Trash2 className="size-4" /></button></div>; })}</div> : null}</article>; })}</div>}</section>;
}

function ReceivablePaymentForm({ receivable, payment, remainingCents, incomeCandidates, onDone }: { receivable: any; payment?: any; remainingCents: number; incomeCandidates: any[]; onDone: () => void }) {
  const mutation = trpc.finance.workspace.receivables.paymentSave.useMutation({ onSuccess: () => { toast.success("Abono guardado y saldo recalculado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ amount: payment ? fromCents(payment.amountCents) : remainingCents ? fromCents(remainingCents) : "", paidAt: payment ? new Date(payment.paidAt).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10), linkedTransactionId: payment?.linkedTransactionId ? String(payment.linkedTransactionId) : "unlinked", notes: payment?.notes || "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: payment?.id, receivableId: receivable.id, linkedTransactionId: form.linkedTransactionId === "unlinked" ? null : Number(form.linkedTransactionId), amountCents: toCents(form.amount), currency: receivable.currency, paidAt: new Date(`${form.paidAt}T12:00:00`).getTime(), notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Importe del abono</Label><Input type="number" min="0.01" step="0.01" max={payment ? undefined : fromCents(remainingCents)} readOnly={Boolean(payment)} required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /><small>{payment ? "Este importe ya fue registrado; aquí sólo se concilia con el ingreso real." : `Saldo disponible: ${formatMoney(remainingCents, receivable.currency)}.`}</small></div><div className="form-field"><Label>Fecha de cobro</Label><Input type="date" required value={form.paidAt} onChange={event => setForm({ ...form, paidAt: event.target.value })} /></div><div className="form-field span-2"><Label>Ingreso real ya registrado</Label><select value={form.linkedTransactionId} onChange={event => setForm({ ...form, linkedTransactionId: event.target.value })}><option value="unlinked">Aún no vincular</option>{incomeCandidates.map(transaction => <option key={transaction.id} value={transaction.id}>{formatDate(transaction.occurredAt)} · {formatMoney(transaction.amountCents, transaction.currency)} · {transaction.notes || `Ingreso #${transaction.id}`}</option>)}</select><small>Solo se vincula a un ingreso aprobado y en la misma moneda. Meximoney no crea ni duplica el ingreso.</small></div><div className="form-field span-2"><Label>Nota del abono</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending || (!payment && remainingCents === 0)}>{mutation.isPending ? "Guardando…" : payment ? "Vincular ingreso" : "Guardar abono"}</Button></div></form>;
}

function ReceivableForm({ currency, entities, projects, onDone }: { currency: string; entities: any[]; projects: any[]; onDone: () => void }) {
  const mutation = trpc.finance.workspace.receivables.save.useMutation({ onSuccess: () => { toast.success("Cuenta por cobrar guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ counterparty: "", origin: "", scope: "personal", entityId: "", projectId: "", amount: "", currency, issuedAt: new Date().toISOString().slice(0, 10), dueAt: "", notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, counterparty: form.counterparty, origin: form.origin, scope: form.scope as any, amountCents: toCents(form.amount), currency: form.currency.toUpperCase(), issuedAt: new Date(`${form.issuedAt}T12:00:00`).getTime(), dueAt: form.dueAt ? new Date(`${form.dueAt}T12:00:00`).getTime() : null, paidAt: null, status: "pending", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground">Una CxC registra un importe que te deben. Los abonos y el vínculo con el ingreso real se registran después, sin crear ni duplicar movimientos.</div></div><div className="form-field"><Label>Cliente o persona</Label><Input required placeholder="Ej. Cliente YMC o nombre de la persona" value={form.counterparty} onChange={event => setForm({ ...form, counterparty: event.target.value })} /></div><div className="form-field"><Label>Origen de la CxC</Label><Input required placeholder="Ej. Servicio YMC, préstamo personal, venta" value={form.origin} onChange={event => setForm({ ...form, origin: event.target.value })} /></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixta</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field"><Label>Importe</Label><Input type="number" min="0.01" step="0.01" required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></div><div className="form-field"><Label>Moneda</Label><Input maxLength={3} required value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div><div className="form-field"><Label>Fecha de origen</Label><Input type="date" required value={form.issuedAt} onChange={event => setForm({ ...form, issuedAt: event.target.value })} /></div><div className="form-field"><Label>Fecha esperada de cobro</Label><Input type="date" value={form.dueAt} onChange={event => setForm({ ...form, dueAt: event.target.value })} /></div><div className="form-field span-2"><Label>Notas</Label><Textarea placeholder="Ej. Factura emitida, condiciones acordadas o recordatorio manual" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : "Guardar cuenta por cobrar"}</Button></div></form>;
}

function PayablesPanel({ snapshot, onCreate, refresh }: { snapshot: any; onCreate: () => void; refresh: () => void }) {
  const remove = trpc.finance.workspace.payables.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const removePayment = trpc.finance.workspace.payables.paymentRemove.useMutation({ onSuccess: () => { toast.success("Pago eliminado y saldo recalculado"); refresh(); }, onError: error => toast.error(error.message) });
  const labels: Record<string, string> = { pending: "Pendiente", overdue: "Vencida", paid: "Pagada", reconciled: "Conciliada" };
  const items = snapshot.payables.slice().sort((a: any, b: any) => (a.dueAt ? new Date(a.dueAt).getTime() : Infinity) - (b.dueAt ? new Date(b.dueAt).getTime() : Infinity));
  const dated = items.filter((item: any) => item.dueAt);
  return <section className="space-y-4">{dated.length ? <div className="content-card"><div className="card-title-row"><div><h2>Próximos vencimientos</h2><p>Agenda manual ordenada por fecha; no crea pagos ni recordatorios automáticos.</p></div></div><div className="flex flex-wrap gap-2">{dated.slice(0, 8).map((item: any) => <div key={`due-${item.id}`} className="rounded-xl border bg-muted/30 px-3 py-2 text-sm"><strong>{formatDate(item.dueAt)}</strong><span className="ml-2 text-muted-foreground">{item.creditor} · {formatMoney(item.amountCents, item.currency)}</span></div>)}</div></div> : null}<div className="content-card">{items.length === 0 ? <PlanningEmpty icon={WalletCards} title="Sin cuentas por pagar" text="Registra una obligación con tu contador, proveedor digital, socio, amistad u otro acreedor. No contará como gasto hasta registrar el pago real." actionLabel="Registrar primera CxP" onAction={onCreate} /> : <div className="debt-list">{items.map((item: any) => { const payments = snapshot.payablePayments.filter((payment: any) => payment.payableId === item.id); const paidCents = payments.reduce((sum: number, payment: any) => sum + payment.amountCents, 0); const remainingCents = Math.max(0, item.amountCents - paidCents); const unlinkedPayment = payments.find((payment: any) => !payment.linkedTransactionId); const expenseCandidates = snapshot.transactions.filter((transaction: any) => transaction.type === "expense" && transaction.currency === item.currency && transaction.reviewStatus === "approved"); const canOpenPayment = remainingCents > 0 || Boolean(unlinkedPayment); return <article key={item.id} className="debt-row"><div className={`debt-priority priority-${item.status === "overdue" ? "critical" : item.status === "pending" ? "medium" : "low"}`} /><div className="debt-main"><div><span className={`scope-pill scope-${item.scope}`}>{scopeLabel[item.scope]}</span><h2>{item.creditor}</h2><p>{item.origin}</p></div><div className="debt-amount"><strong>{formatMoney(item.amountCents, item.currency)}</strong><small>{labels[item.status]}</small></div></div><div className="debt-meta"><span><small>Pagado</small><strong>{formatMoney(paidCents, item.currency)}</strong></span><span><small>Saldo pendiente</small><strong>{formatMoney(remainingCents, item.currency)}</strong></span><span><small>Vence</small><strong>{item.dueAt ? formatDate(item.dueAt) : "Sin fecha"}</strong></span><span><small>Conciliación</small><strong>{item.status === "reconciled" ? "Gasto vinculado" : item.status === "paid" ? "Falta vincular gasto" : "Pendiente"}</strong></span></div><div className="debt-foot"><p>{item.notes || "Cada pago puede vincularse al gasto real ya registrado, sin crear movimientos nuevos."}</p><div className="flex flex-wrap gap-2"><Dialog><DialogTrigger asChild><Button size="sm" variant="ghost" aria-label={`Editar ${item.creditor}`}><Pencil className="mr-1 h-3.5 w-3.5"/>Editar</Button></DialogTrigger><DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar cuenta por pagar</DialogTitle><DialogDescription>La edición conserva los pagos y conciliaciones existentes.</DialogDescription></DialogHeader><PayableForm currency={item.currency} entities={snapshot.entities} projects={snapshot.projects} editing={item} onDone={refresh} /></DialogContent></Dialog>{canOpenPayment ? <Dialog><DialogTrigger asChild><Button size="sm" variant="outline">{unlinkedPayment ? "Vincular gasto" : "Registrar pago"}</Button></DialogTrigger><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>{unlinkedPayment ? "Conciliar pago con gasto real" : "Registrar pago parcial"}</DialogTitle><DialogDescription>El pago no crea un gasto. Selecciona, si existe, el gasto que ya registraste manualmente.</DialogDescription></DialogHeader><PayablePaymentForm payable={item} payment={unlinkedPayment} remainingCents={remainingCents} expenseCandidates={expenseCandidates} onDone={refresh} /></DialogContent></Dialog> : <Button size="sm" variant="outline" disabled>Conciliada</Button>}<button className="row-action-danger" aria-label="Eliminar cuenta por pagar" onClick={() => { if (confirm("¿Eliminar esta cuenta por pagar manual?")) remove.mutate({ id: item.id }); }}><Trash2 className="size-4" /></button></div></div>{payments.length ? <div className="mt-3 space-y-2 border-t pt-3">{payments.map((payment: any) => { const expense = snapshot.transactions.find((transaction: any) => transaction.id === payment.linkedTransactionId); return <div key={payment.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-muted/45 px-3 py-2 text-sm"><span><strong>{formatMoney(payment.amountCents, payment.currency)}</strong> · {formatDate(payment.paidAt)} · {expense ? `Gasto vinculado: ${expense.notes || `#${expense.id}`}` : "Sin gasto vinculado"}</span><button className="row-action-danger" aria-label="Eliminar pago" onClick={() => { if (confirm("¿Eliminar este pago y recalcular el saldo?")) removePayment.mutate({ id: payment.id }); }}><Trash2 className="size-4" /></button></div>; })}</div> : null}</article>; })}</div>}</div></section>;
}

function PayablePaymentForm({ payable, payment, remainingCents, expenseCandidates, onDone }: { payable: any; payment?: any; remainingCents: number; expenseCandidates: any[]; onDone: () => void }) {
  const mutation = trpc.finance.workspace.payables.paymentSave.useMutation({ onSuccess: () => { toast.success("Pago guardado y saldo recalculado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ amount: payment ? fromCents(payment.amountCents) : remainingCents ? fromCents(remainingCents) : "", paidAt: payment ? new Date(payment.paidAt).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10), linkedTransactionId: payment?.linkedTransactionId ? String(payment.linkedTransactionId) : "unlinked", notes: payment?.notes || "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: payment?.id, payableId: payable.id, linkedTransactionId: form.linkedTransactionId === "unlinked" ? null : Number(form.linkedTransactionId), amountCents: toCents(form.amount), currency: payable.currency, paidAt: new Date(`${form.paidAt}T12:00:00`).getTime(), notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Importe del pago</Label><Input type="number" min="0.01" step="0.01" max={payment ? undefined : fromCents(remainingCents)} readOnly={Boolean(payment)} required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /><small>{payment ? "Este importe ya fue registrado; aquí sólo se concilia con el gasto real." : `Saldo disponible: ${formatMoney(remainingCents, payable.currency)}.`}</small></div><div className="form-field"><Label>Fecha de pago</Label><Input type="date" required value={form.paidAt} onChange={event => setForm({ ...form, paidAt: event.target.value })} /></div><div className="form-field span-2"><Label>Gasto real ya registrado</Label><select value={form.linkedTransactionId} onChange={event => setForm({ ...form, linkedTransactionId: event.target.value })}><option value="unlinked">Aún no vincular</option>{expenseCandidates.map(transaction => <option key={transaction.id} value={transaction.id}>{formatDate(transaction.occurredAt)} · {formatMoney(transaction.amountCents, transaction.currency)} · {transaction.notes || `Gasto #${transaction.id}`}</option>)}</select><small>Solo se vincula a un gasto aprobado y en la misma moneda. Meximoney no crea ni duplica el gasto.</small></div><div className="form-field span-2"><Label>Nota del pago</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending || (!payment && remainingCents === 0)}>{mutation.isPending ? "Guardando…" : payment ? "Vincular gasto" : "Guardar pago"}</Button></div></form>;
}

function PayableForm({ currency, entities, projects, editing, onDone }: { currency: string; entities: any[]; projects: any[]; editing?: any; onDone: () => void }) {
  const mutation = trpc.finance.workspace.payables.save.useMutation({ onSuccess: () => { toast.success("Cuenta por pagar guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ creditor: editing?.creditor ?? "", origin: editing?.origin ?? "", scope: editing?.scope ?? "personal", entityId: editing?.entityId?.toString() ?? "", projectId: editing?.projectId?.toString() ?? "", amount: editing ? fromCents(editing.amountCents) : "", currency: editing?.currency ?? currency, issuedAt: editing?.issuedAt ? new Date(editing.issuedAt).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10), dueAt: editing?.dueAt ? new Date(editing.dueAt).toISOString().slice(0, 10) : "", notes: editing?.notes ?? "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: editing?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, creditor: form.creditor, origin: form.origin, scope: form.scope as any, amountCents: toCents(form.amount), currency: form.currency.toUpperCase(), issuedAt: new Date(`${form.issuedAt}T12:00:00`).getTime(), dueAt: form.dueAt ? new Date(`${form.dueAt}T12:00:00`).getTime() : null, paidAt: editing?.paidAt ? new Date(editing.paidAt).getTime() : null, status: editing?.status ?? "pending", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground">Una CxP registra una obligación pendiente. Los pagos y su vínculo con el gasto real se registran después, sin crear ni duplicar movimientos.</div></div><div className="form-field"><Label>Acreedor</Label><Input required placeholder="Ej. Notion, contador, socio o amistad" value={form.creditor} onChange={event => setForm({ ...form, creditor: event.target.value })} /></div><div className="form-field"><Label>Origen de la CxP</Label><Input required placeholder="Ej. Suscripción, honorarios, préstamo o anticipo" value={form.origin} onChange={event => setForm({ ...form, origin: event.target.value })} /></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixta</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field"><Label>Importe</Label><Input type="number" min="0.01" step="0.01" required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></div><div className="form-field"><Label>Moneda</Label><Input maxLength={3} required value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div><div className="form-field"><Label>Fecha de origen</Label><Input type="date" required value={form.issuedAt} onChange={event => setForm({ ...form, issuedAt: event.target.value })} /></div><div className="form-field"><Label>Fecha esperada de pago</Label><Input type="date" value={form.dueAt} onChange={event => setForm({ ...form, dueAt: event.target.value })} /></div><div className="form-field span-2"><Label>Notas</Label><Textarea placeholder="Ej. Condiciones, referencia o recordatorio manual" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : "Guardar cuenta por pagar"}</Button></div></form>;
}

function RecurringTemplatesPanel({ snapshot, onCreate, refresh }: { snapshot: any; onCreate: () => void; refresh: () => void }) {
  const remove = trpc.finance.workspace.recurringTemplates.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const apply = trpc.finance.workspace.recurringTemplates.applyNow.useMutation({ onSuccess: () => { toast.success("Plantilla aplicada como un movimiento manual confirmado"); refresh(); }, onError: error => toast.error(error.message) });
  const cadence: Record<string, string> = { weekly: "Semanal", monthly: "Mensual", quarterly: "Trimestral", annual: "Anual" };
  const templates = snapshot.recurringTemplates.slice().sort((a: any, b: any) => a.name.localeCompare(b.name));
  return <section className="content-card">{templates.length === 0 ? <PlanningEmpty icon={FileClock} title="Sin plantillas recurrentes" text="Crea plantillas para Notion, Squarespace, Google Workspace, contador o cualquier proveedor. Se aplican manualmente; no se generan cargos automáticos." actionLabel="Crear primera plantilla" onAction={onCreate} /> : <div className="debt-list">{templates.map((template: any) => <article key={template.id} className="debt-row"><div className={`debt-priority priority-${template.status === "active" ? "medium" : "low"}`} /><div className="debt-main"><div><span className={`scope-pill scope-${template.scope}`}>{scopeLabel[template.scope]}</span><h2>{template.name}</h2><p>{template.counterparty || "Proveedor o contraparte pendiente"} · {cadence[template.cadence]} · {template.status === "active" ? "Activa" : "Pausada"}</p></div><div className="debt-amount"><strong>{formatMoney(template.amountCents, template.currency)}</strong><small>{template.type === "expense" ? "Gasto" : "Ingreso"}</small></div></div><div className="debt-foot"><p>{template.notes || "Aplica esta plantilla manualmente cuando confirmes que corresponde registrar el movimiento."}</p><div className="flex flex-wrap gap-2"><Dialog><DialogTrigger asChild><Button size="sm" variant="ghost"><Pencil className="mr-1 h-3.5 w-3.5"/>Editar</Button></DialogTrigger><DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Editar plantilla recurrente</DialogTitle><DialogDescription>Los movimientos ya aplicados no se alteran. La plantilla sólo se usará cuando la apliques de nuevo.</DialogDescription></DialogHeader><RecurringTemplateForm snapshot={snapshot} editing={template} onDone={refresh} /></DialogContent></Dialog><Button size="sm" variant="outline" disabled={template.status !== "active" || apply.isPending} onClick={() => { if (confirm("¿Crear ahora un movimiento confirmado desde esta plantilla?")) apply.mutate({ id: template.id, occurredAt: Date.now() }); }}>Aplicar ahora</Button><button className="row-action-danger" aria-label="Eliminar plantilla recurrente" onClick={() => { if (confirm("¿Eliminar esta plantilla recurrente?")) remove.mutate({ id: template.id }); }}><Trash2 className="size-4" /></button></div></div></article>)}</div>}</section>;
}

function RecurringTemplateForm({ snapshot, editing, onDone }: { snapshot: any; editing?: any; onDone: () => void }) {
  const mutation = trpc.finance.workspace.recurringTemplates.save.useMutation({ onSuccess: () => { toast.success("Plantilla recurrente guardada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ name: editing?.name ?? "", counterparty: editing?.counterparty ?? "", type: editing?.type ?? "expense", scope: editing?.scope ?? "business", entityId: editing?.entityId?.toString() ?? "", projectId: editing?.projectId?.toString() ?? "", accountId: editing?.accountId?.toString() ?? "", categoryId: editing?.categoryId?.toString() ?? "", amount: editing ? fromCents(editing.amountCents) : "", currency: editing?.currency ?? (snapshot.profile?.currency || "MXN"), cadence: editing?.cadence ?? "monthly", nextOccurrenceAt: editing?.nextOccurrenceAt ? new Date(editing.nextOccurrenceAt).toISOString().slice(0, 10) : "", notes: editing?.notes ?? "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ id: editing?.id, entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, accountId: form.accountId ? Number(form.accountId) : null, categoryId: form.categoryId ? Number(form.categoryId) : null, name: form.name, counterparty: form.counterparty || null, type: form.type as any, scope: form.scope as any, amountCents: toCents(form.amount), currency: form.currency.toUpperCase(), incomeNature: editing?.incomeNature ?? "other", cadence: form.cadence as any, nextOccurrenceAt: form.nextOccurrenceAt ? new Date(`${form.nextOccurrenceAt}T12:00:00`).getTime() : null, status: editing?.status ?? "active", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><div className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground">Las plantillas son editables y personalizables para cualquier proveedor. No generan cargos ni movimientos por sí solas: se aplican manualmente.</div></div><div className="form-field"><Label>Nombre de plantilla</Label><Input required placeholder="Ej. Notion mensual" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Proveedor o contraparte</Label><Input placeholder="Ej. Notion, Squarespace, contador" value={form.counterparty} onChange={event => setForm({ ...form, counterparty: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="expense">Gasto</option><option value="income">Ingreso</option></select></div><div className="form-field"><Label>Frecuencia de referencia</Label><select value={form.cadence} onChange={event => setForm({ ...form, cadence: event.target.value })}><option value="weekly">Semanal</option><option value="monthly">Mensual</option><option value="quarterly">Trimestral</option><option value="annual">Anual</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixta</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={snapshot.entities} projects={snapshot.projects} /><div className="form-field"><Label>Cuenta por defecto</Label><select value={form.accountId} onChange={event => setForm({ ...form, accountId: event.target.value })}><option value="">Sin cuenta</option>{snapshot.accounts.map((account: any) => <option key={account.id} value={account.id}>{account.name}</option>)}</select></div><div className="form-field"><Label>Categoría por defecto</Label><select value={form.categoryId} onChange={event => setForm({ ...form, categoryId: event.target.value })}><option value="">Sin categoría</option>{snapshot.categories.filter((category: any) => category.isActive).map((category: any) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><div className="form-field"><Label>Importe</Label><Input type="number" min="0.01" step="0.01" required value={form.amount} onChange={event => setForm({ ...form, amount: event.target.value })} /></div><div className="form-field"><Label>Moneda</Label><Input maxLength={3} required value={form.currency} onChange={event => setForm({ ...form, currency: event.target.value.toUpperCase() })} /></div><div className="form-field span-2"><Label>Próxima fecha de referencia</Label><Input type="date" value={form.nextOccurrenceAt} onChange={event => setForm({ ...form, nextOccurrenceAt: event.target.value })} /></div><div className="form-field span-2"><Label>Notas</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>{mutation.isPending ? "Guardando…" : "Guardar plantilla"}</Button></div></form>;
}

function TasksPanel({ snapshot, onCreate, refresh }: { snapshot: any; onCreate: () => void; refresh: () => void }) {
  const update = trpc.finance.tasks.save.useMutation({ onSuccess: () => { toast.success("Tarea actualizada"); refresh(); }, onError: error => toast.error(error.message) });
  const remove = trpc.finance.tasks.remove.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) });
  const items = snapshot.tasks.slice().sort((a: any, b: any) => (a.dueAt ? new Date(a.dueAt).getTime() : Infinity) - (b.dueAt ? new Date(b.dueAt).getTime() : Infinity));
  const complete = (task: any) => update.mutate({ id: task.id, title: task.title, area: task.area, scope: task.scope, priority: task.priority, status: "completed", dueAt: task.dueAt ? new Date(task.dueAt).getTime() : null, goalId: task.goalId, debtId: task.debtId, requiresConfirmation: task.requiresConfirmation, notes: task.notes });
  return <section className="content-card">{items.length === 0 ? <PlanningEmpty icon={ListTodo} title="No hay tareas financieras" text="Crea una próxima acción concreta con una fecha y prioridad. Meximoney no ejecutará ninguna operación por ti." actionLabel="Crear tarea" onAction={onCreate} /> : <div className="task-list task-list-large">{items.map((task: any) => <article className={`task-row task-row-large ${task.status === "completed" ? "task-completed" : ""}`} key={task.id}><button className="task-check" aria-label="Marcar tarea completada" onClick={() => complete(task)} disabled={task.status === "completed"}>{task.status === "completed" ? <Check className="size-4" /> : null}</button><span className={`priority-dot priority-${task.priority}`} /><div><strong>{task.title}</strong><small>{task.dueAt ? `Vence ${formatDate(task.dueAt)}` : "Sin fecha"} · {scopeLabel[task.scope]} · {task.requiresConfirmation ? "Requiere confirmación" : "Seguimiento"}</small>{task.notes ? <p>{task.notes}</p> : null}</div><span className="task-priority">{priorityLabel[task.priority]}</span><button className="row-action-danger" aria-label="Eliminar tarea" onClick={() => { if (confirm("¿Eliminar esta tarea?") ) remove.mutate({ id: task.id }); }}><Trash2 className="size-4" /></button></article>)}</div>}</section>;
}

function ReviewsPanel({ snapshot, currency, onCreate }: { snapshot: any; currency: string; onCreate: () => void }) {
  const reviews = snapshot.reviews.slice().sort((a: any, b: any) => new Date(b.periodStart).getTime() - new Date(a.periodStart).getTime());
  return <section className="content-card">{reviews.length === 0 ? <PlanningEmpty icon={CalendarCheck2} title="Aún no hay revisiones mensuales" text="Al cierre del mes, registra resultados, aprendizajes y tus tres siguientes acciones." actionLabel="Crear primera revisión" onAction={onCreate} /> : <div className="review-list">{reviews.map((review: any) => <article className="review-row" key={review.id}><div className="review-period"><CalendarCheck2 className="size-5" /><div><strong className="capitalize">{formatDate(review.periodStart, { month: "long", year: "numeric" })}</strong><small>{review.status === "closed" ? "Cierre completado" : review.status === "reviewed" ? "Revisada" : "Borrador"}</small></div></div><div><small>Ingresos</small><strong>{formatMoney(review.incomeCents, currency)}</strong></div><div><small>Gastos</small><strong>{formatMoney(review.expenseCents, currency)}</strong></div><div><small>Flujo neto</small><strong className={review.netCashFlowCents >= 0 ? "amount-positive" : "amount-negative"}>{formatMoney(review.netCashFlowCents, currency)}</strong></div><ChevronRight className="size-4 text-muted-foreground" /></article>)}</div>}</section>;
}

function DecisionsPanel({ snapshot, onCreate }: { snapshot: any; onCreate: () => void }) {
  const remove = trpc.finance.decisions.remove.useMutation({ onSuccess: () => window.location.reload(), onError: error => toast.error(error.message) });
  return <section className="decision-grid">{snapshot.decisions.length === 0 ? <section className="content-card"><PlanningEmpty icon={Scale} title="Sin decisiones registradas" text="Documenta el motivo, datos utilizados, hipótesis, riesgos, alternativas y fecha de revisión de las decisiones relevantes." actionLabel="Registrar decisión" onAction={onCreate} /></section> : snapshot.decisions.map((decision: any) => <article className="decision-card" key={decision.id}><div className="card-title-row"><div><span className="decision-status">{decision.status === "approved" ? "Aprobada" : decision.status === "proposal" ? "Propuesta" : decision.status === "reviewed" ? "Revisada" : "Descartada"}</span><h2>{decision.title}</h2><p>{decision.area} · {formatDate(decision.createdAt)}</p></div><button className="row-action-danger" aria-label="Eliminar decisión" onClick={() => { if (confirm("¿Eliminar esta decisión?") ) remove.mutate({ id: decision.id }); }}><Trash2 className="size-4" /></button></div><div className="decision-detail"><strong>Datos usados</strong><p>{decision.dataUsed || "Pendiente de documentar"}</p></div><div className="decision-detail"><strong>Supuestos y riesgos</strong><p>{decision.assumptions || "Sin supuestos registrados"}{decision.risks ? ` · Riesgos: ${decision.risks}` : ""}</p></div><div className="decision-detail"><strong>Alternativas</strong><p>{decision.alternatives || "Sin alternativas registradas"}</p></div><div className="decision-detail"><strong>Revisión</strong><p>{decision.reviewAt ? formatDate(decision.reviewAt) : "Fecha de revisión pendiente"}</p></div></article>)}</section>;
}

function EntityProjectFields({ form, setForm, entities, projects }: { form: any; setForm: (value: any) => void; entities: any[]; projects: any[] }) { const availableProjects = projects.filter(project => !form.entityId || project.entityId === Number(form.entityId)); return <><div className="form-field"><Label>Entidad</Label><select value={form.entityId} onChange={event => setForm({ ...form, entityId: event.target.value, projectId: "" })}><option value="">Sin entidad / personal</option>{entities.map(entity => <option key={entity.id} value={entity.id}>{entity.shortCode || entity.name}</option>)}</select></div><div className="form-field"><Label>Proyecto</Label><select value={form.projectId} onChange={event => setForm({ ...form, projectId: event.target.value })}><option value="">Sin proyecto</option>{availableProjects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select></div></>; }

function BudgetForm({ categories, entities, projects, onDone }: { categories: any[]; entities: any[]; projects: any[]; onDone: () => void }) {
  const mutation = trpc.finance.budgets.save.useMutation({ onSuccess: () => { toast.success("Partida presupuestaria creada"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ categoryId: "", scope: "personal", type: "expense", entityId: "", projectId: "", planned: "", period: new Date().toISOString().slice(0, 7), notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, categoryId: form.categoryId ? Number(form.categoryId) : null, scope: form.scope as any, type: form.type as any, plannedCents: toCents(form.planned), periodStart: new Date(`${form.period}-01T12:00:00`).getTime(), notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field"><Label>Periodo</Label><Input type="month" required value={form.period} onChange={event => setForm({ ...form, period: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="expense">Gasto</option><option value="income">Ingreso</option></select></div><div className="form-field"><Label>Categoría</Label><select value={form.categoryId} onChange={event => setForm({ ...form, categoryId: event.target.value })}><option value="">Sin categoría</option>{categories.filter(category => category.isActive).map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field span-2"><Label>Importe previsto</Label><Input type="number" min="0" step="0.01" required value={form.planned} onChange={event => setForm({ ...form, planned: event.target.value })} /></div><div className="form-field span-2"><Label>Nota</Label><Textarea value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar partida</Button></div></form>;
}

function GoalForm({ currency, entities, projects, onDone }: { currency: string; entities: any[]; projects: any[]; onDone: () => void }) {
  const mutation = trpc.finance.goals.save.useMutation({ onSuccess: () => { toast.success("Objetivo creado"); onDone(); }, onError: error => toast.error(error.message) });
  const [form, setForm] = useState({ name: "", type: "emergency", scope: "personal", entityId: "", projectId: "", target: "", current: "0", contribution: "0", targetDate: "", priority: "medium", notes: "" });
  const submit = (event: FormEvent) => { event.preventDefault(); mutation.mutate({ entityId: form.entityId ? Number(form.entityId) : null, projectId: form.projectId ? Number(form.projectId) : null, name: form.name, type: form.type as any, scope: form.scope as any, targetCents: toCents(form.target), currentCents: toCents(form.current), monthlyContributionCents: toCents(form.contribution), currency, targetDate: form.targetDate ? new Date(`${form.targetDate}T12:00:00`).getTime() : null, priority: form.priority as any, status: "active", notes: form.notes || null }); };
  return <form className="form-grid" onSubmit={submit}><div className="form-field span-2"><Label>Nombre del objetivo</Label><Input required placeholder="Ej. Fondo de emergencia" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></div><div className="form-field"><Label>Tipo</Label><select value={form.type} onChange={event => setForm({ ...form, type: event.target.value })}><option value="emergency">Emergencia</option><option value="debt">Amortizar deuda</option><option value="housing">Vivienda</option><option value="retirement">Jubilación</option><option value="investment">Inversión</option><option value="education">Educación</option><option value="business">Negocio</option><option value="other">Otro</option></select></div><div className="form-field"><Label>Área</Label><select value={form.scope} onChange={event => setForm({ ...form, scope: event.target.value })}><option value="personal">Personal</option><option value="business">Empresarial</option><option value="mixed">Mixto</option></select></div><EntityProjectFields form={form} setForm={setForm} entities={entities} projects={projects} /><div className="form-field"><Label>Importe objetivo</Label><Input type="number" min="0.01" step="0.01" required value={form.target} onChange={event => setForm({ ...form, target: event.target.value })} /></div><div className="form-field"><Label>Importe actual</Label><Input type="number" min="0" step="0.01" value={form.current} onChange={event => setForm({ ...form, current: event.target.value })} /></div><div className="form-field"><Label>Aportación mensual</Label><Input type="number" min="0" step="0.01" value={form.contribution} onChange={event => setForm({ ...form, contribution: event.target.value })} /></div><div className="form-field"><Label>Fecha objetivo</Label><Input type="date" value={form.targetDate} onChange={event => setForm({ ...form, targetDate: event.target.value })} /></div><div className="form-field"><Label>Prioridad</Label><select value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}><option value="critical">Crítica</option><option value="high">Alta</option><option value="medium">Media</option><option value="low">Baja</option></select></div><div className="form-field span-2"><Label>Supuestos o riesgos</Label><Textarea placeholder="Ej. Aportación solo si los ingresos se mantienen" value={form.notes} onChange={event => setForm({ ...form, notes: event.target.value })} /></div><div className="form-actions span-2"><Button type="submit" disabled={mutation.isPending}>Guardar objetivo</Button></div></form>;
}

